    const session = this.getSession();
    const page = session.getPage();
    if (!page) {
      throw new Error('No page available');
    }

    const hasText = params.hasText as string;
    let locator = page.locator(selector);
    if (hasText) {
      locator = locator.filter({ hasText: hasText });
